use serde::{Deserialize, Serialize};

pub(super) const GENERATED_BY: &str =
    "Generated by: redlinedb-bench sqlite_parity jankurai-compare";
pub(super) const GENERATED_SOURCE: &str =
    "Source: .jankurai/repo-score.json; target/sqlite-jankurai/repo-score.json";
pub(super) const GENERATED_COMMAND: &str = "Command: just sqlite-jankurai-compare";
pub(super) const DO_NOT_EDIT: &str = "DO NOT EDIT BY HAND.";
pub(super) const REPORT_GENERATED_BY: &str = "redlinedb-bench sqlite_parity report";
pub(super) const REPORT_REGEN_COMMAND: &str = "just sqlite-parity-report-update";

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub(crate) struct JankuraiComparison {
    #[serde(default = "generated_by")]
    pub(crate) generated_by: String,
    #[serde(default = "generated_source")]
    pub(crate) source: String,
    #[serde(default = "generated_command")]
    pub(crate) command: String,
    #[serde(default = "do_not_edit")]
    pub(crate) do_not_edit_by_hand: String,
    pub(crate) schema_version: String,
    pub(crate) updated_date: String,
    pub(crate) sqlite_ref: String,
    pub(crate) repositories: Vec<JankuraiRepository>,
    pub(crate) issue_breakdown: Vec<IssueBreakdown>,
    pub(crate) code_shape: Vec<CodeShapeScore>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub(crate) struct JankuraiRepository {
    pub(crate) id: String,
    pub(crate) label: String,
    pub(crate) source_ref: String,
    pub(crate) score: u64,
    pub(crate) raw_score: u64,
    pub(crate) hard_findings: u64,
    pub(crate) soft_findings: u64,
    pub(crate) caps_applied: u64,
    pub(crate) decision: String,
    pub(crate) dimensions: Vec<DimensionScore>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub(crate) struct DimensionScore {
    pub(crate) name: String,
    pub(crate) score: f64,
    pub(crate) weight: Option<f64>,
    pub(crate) weighted_points: Option<f64>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub(crate) struct IssueBreakdown {
    pub(crate) repo_id: String,
    pub(crate) repo_label: String,
    pub(crate) category: String,
    pub(crate) lane: String,
    pub(crate) hard_findings: u64,
    pub(crate) soft_findings: u64,
    pub(crate) total_findings: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub(crate) struct CodeShapeScore {
    pub(crate) repo_id: String,
    pub(crate) repo_label: String,
    pub(crate) dimension: String,
    pub(crate) score: f64,
    pub(crate) weighted_points: Option<f64>,
}

pub(super) fn generated_by() -> String {
    GENERATED_BY.to_owned()
}

pub(super) fn generated_source() -> String {
    GENERATED_SOURCE.to_owned()
}

pub(super) fn generated_command() -> String {
    GENERATED_COMMAND.to_owned()
}

pub(super) fn do_not_edit() -> String {
    DO_NOT_EDIT.to_owned()
}
